package com.ahsim.demulation;

import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Paint;
import android.graphics.RectF;
import android.graphics.Typeface;

/**
 * Dune / Sega Genesis HUD helper.
 *
 * All coordinates are device pixels. The radar and the three square buttons
 * are derived from a single 72-unit logical grid, so the row stays perfectly
 * even on every screen scale.
 */
public final class DuneSegaHud {
    private static Typeface cachedTypeface;
    private static Context appContext;

    private DuneSegaHud() {}

    public static Typeface typeface(Context context) {
        if (context != null) {
            Context app = context.getApplicationContext();
            appContext = app != null ? app : context;
        }
        if (cachedTypeface != null) return cachedTypeface;
        Context c = context != null ? context : appContext;
        Typeface result = Typeface.MONOSPACE;
        if (c != null) {
            try {
                Typeface custom = Typeface.createFromAsset(
                        c.getAssets(), "fonts/dune_sega.ttf");
                if (custom != null) result = custom;
            } catch (Throwable ignored) {
                // Keep monospace if the packaged font cannot be read.
            }
            cachedTypeface = result;
        }
        return result;
    }

    /** Called once from the view constructor; invalidates any early cache. */
    public static void init(Context context) {
        appContext = context;
        cachedTypeface = null;
        typeface(context);
    }

    /**
     * Applies the Dune font. Never caches a fallback face when no context is
     * known yet, otherwise the whole HUD would stay monospace forever.
     */
    public static void applyFont(Paint paint) {
        if (paint == null) return;
        Typeface tf = cachedTypeface;
        if (tf == null && appContext != null) tf = typeface(appContext);
        if (tf != null) paint.setTypeface(tf);
        paint.setFakeBoldText(false);
    }

    /** Fits the radar inside a viewport; kept for callers that need it. */
    public static void fitRadar(RectF viewport, RectF radar, float margin) {
        if (radar == null) return;
        if (viewport == null || viewport.isEmpty()) {
            radar.setEmpty();
            return;
        }
        float availableW = viewport.width() - 2f * margin;
        float availableH = viewport.height() - 2f * margin;
        if (availableW <= 2f || availableH <= 2f) {
            radar.setEmpty();
            return;
        }
        float size = Math.min(availableW, availableH);
        float left = viewport.right - margin - size;
        float top = viewport.bottom - margin - size;
        radar.set(left, top, left + size, top + size);
    }

    /**
     * Three equal square buttons in one row directly above the radar.
     * slot 0 = menu, slot 1 = units, slot 2 = base; slots 3+ form extra rows.
     * Gaps are proportional to the radar, so the row is pixel-even at any
     * device scale and never depends on an unrelated screen density value.
     */
    public static void aboveRadarRect(RectF radar, float scale, int slot, RectF out) {
        if (out == null) return;
        if (radar == null || radar.isEmpty()) {
            out.setEmpty();
            return;
        }
        float w = radar.width();
        float gap = w * (4f / 72f);          // 4 logical units between buttons
        float rowGap = w * (8f / 72f);       // 8 logical units above the radar
        float size = (w - 2f * gap) / 3f;    // exact equal thirds
        if (size < 8f) {
            out.setEmpty();
            return;
        }
        int column = slot % 3;
        int row = slot / 3;
        float right = radar.right;
        float bottom = radar.top - rowGap - row * (size + rowGap);
        float left = right - size - (2 - column) * (size + gap);
        out.set(left, bottom - size, left + size, bottom);
    }

    public static void drawHudButton(Canvas canvas, RectF r, int kind, boolean enabled,
                                     Paint fill, Paint line) {
        if (canvas == null || r == null || r.isEmpty() || fill == null || line == null) return;
        float s = Math.max(1f, r.width() / 20f);
        float l = r.left, t = r.top, rt = r.right, b = r.bottom;

        fill.setStyle(Paint.Style.FILL);
        fill.setColor(0xAA000000);
        canvas.drawRect(l + 1.2f*s, t + 1.2f*s, rt + 1.2f*s, b + 1.2f*s, fill);

        fill.setColor(0xFF0B0E10);
        canvas.drawRect(l, t, rt, b, fill);

        line.setStyle(Paint.Style.STROKE);
        line.setStrokeWidth(Math.max(1f, 1.1f*s));
        line.setColor(enabled ? 0xFFD8B75C : 0xFF6B6350);
        canvas.drawRect(l + .5f*s, t + .5f*s, rt - .5f*s, b - .5f*s, line);

        float in = 1.8f*s;
        fill.setColor(enabled ? 0xFF2A2417 : 0xFF171715);
        canvas.drawRect(l+in, t+in, rt-in, b-in, fill);
        line.setStrokeWidth(Math.max(.8f, .9f*s));
        line.setColor(0xFFF4DE9B);
        canvas.drawLine(l+in, t+in, l+in, b-in, line);
        canvas.drawLine(l+in, t+in, rt-in, t+in, line);
        line.setColor(0xFF6E4A1C);
        canvas.drawLine(rt-in, t+in, rt-in, b-in, line);
        canvas.drawLine(l+in, b-in, rt-in, b-in, line);

        fill.setColor(enabled ? 0xFFFFE39A : 0xFF5C5748);
        float d = .9f*s;
        canvas.drawRect(l+1f*s, t+1f*s, l+1f*s+d, t+1f*s+d, fill);
        canvas.drawRect(rt-1f*s-d, t+1f*s, rt-1f*s, t+1f*s+d, fill);
        canvas.drawRect(l+1f*s, b-1f*s-d, l+1f*s+d, b-1f*s, fill);
        canvas.drawRect(rt-1f*s-d, b-1f*s-d, rt-1f*s, b-1f*s, fill);

        line.setColor(enabled ? 0xFFFFE7AE : 0xFF7A7462);
        if (kind == 0) drawUnitsIcon(canvas, r, s, line);
        else if (kind == 2) drawMenuIcon(canvas, r, s, line);
        else drawBaseIcon(canvas, r, s, line);
    }

    /** Three stacked bars, the classic Genesis "menu" glyph. */
    private static void drawMenuIcon(Canvas c, RectF r, float s, Paint p) {
        float cx = r.centerX(), cy = r.centerY();
        p.setStyle(Paint.Style.FILL);
        p.setColor(0xFFFFE7AE);
        float halfW = 5.6f * s;
        float h = 1.6f * s;
        float step = 3.4f * s;
        c.drawRect(cx - halfW, cy - step - h / 2f, cx + halfW, cy - step + h / 2f, p);
        c.drawRect(cx - halfW, cy - h / 2f, cx + halfW, cy + h / 2f, p);
        c.drawRect(cx - halfW, cy + step - h / 2f, cx + halfW, cy + step + h / 2f, p);
    }

    private static void drawUnitsIcon(Canvas c, RectF r, float s, Paint p) {
        float cx = r.centerX(), cy = r.centerY() + .5f*s;
        p.setStyle(Paint.Style.STROKE);
        p.setStrokeWidth(Math.max(1f, 1.15f*s));
        p.setColor(0xFFFFE7AE);
        RectF a = new RectF(cx-5.6f*s, cy-2.6f*s, cx-.8f*s, cy+2.6f*s);
        RectF b = new RectF(cx+.8f*s, cy-2.6f*s, cx+5.6f*s, cy+2.6f*s);
        int sv = c.save();
        c.rotate(-30f, cx-3.4f*s, cy);
        c.drawOval(a, p);
        c.restoreToCount(sv);
        sv = c.save();
        c.rotate(-30f, cx+3.4f*s, cy);
        c.drawOval(b, p);
        c.restoreToCount(sv);
        c.drawLine(cx-1.8f*s, cy+1.2f*s, cx+1.8f*s, cy-1.2f*s, p);
    }

    private static void drawBaseIcon(Canvas c, RectF r, float s, Paint p) {
        float cx = r.centerX(), cy = r.centerY() + .5f*s;
        p.setStyle(Paint.Style.STROKE);
        p.setStrokeWidth(Math.max(1f, 1.05f*s));
        p.setColor(0xFFFFE7AE);
        c.drawRect(cx-5.8f*s, cy-.3f*s, cx+5.8f*s, cy+5f*s, p);
        c.drawLine(cx-6.5f*s, cy-.3f*s, cx-3.8f*s, cy-4.2f*s, p);
        c.drawLine(cx-3.8f*s, cy-4.2f*s, cx+3.8f*s, cy-4.2f*s, p);
        c.drawLine(cx+3.8f*s, cy-4.2f*s, cx+6.5f*s, cy-.3f*s, p);
        c.drawLine(cx-2.5f*s, cy+5f*s, cx-2.5f*s, cy-4.2f*s, p);
        c.drawLine(cx+2.5f*s, cy+5f*s, cx+2.5f*s, cy+.8f*s, p);
        c.drawLine(cx+2.5f*s, cy+.8f*s, cx+5.8f*s, cy+.8f*s, p);
    }
}

